```python
import re
from datetime import datetime


def dedupe_contacts(rows):
    ANGLE_RE = re.compile(r"<([^<>]*)>")
    EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
    ZIP4_RE = re.compile(r"([0-9]{5})-[0-9]{4}")
    ZIP5_RE = re.compile(r"[0-9]{5}")
    ZIP_SHORT_RE = re.compile(r"[0-9]{4}")
    NON_DIGIT_RE = re.compile(r"[^0-9]")
    TAG_SPLIT_RE = re.compile(r"[;,]")
    DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
    GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
    OPT_OUT_VALUES = {"y", "yes", "true", "1"}

    def get(row, key):
        v = row.get(key, "")
        return "" if v is None else str(v)

    def norm_email(raw):
        s = raw
        m = ANGLE_RE.search(s)
        if m:
            s = m.group(1)
        s = s.strip().lower()
        if s.count("@") == 1:
            local, domain = s.split("@")
            if domain in GMAIL_DOMAINS:
                local = local.replace(".", "").split("+")[0]
                domain = "gmail.com"
            s = local + "@" + domain
        # validation
        if s.count("@") != 1:
            return ""
        local, domain = s.split("@")
        if not local:
            return ""
        if "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return s

    def norm_phone(raw):
        m = EXT_RE.search(raw)
        if m:
            raw = raw[:m.start()]
        digits = NON_DIGIT_RE.sub("", raw)
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def norm_zip(raw):
        z = raw.strip()
        m = ZIP4_RE.fullmatch(z)
        if m:
            z = m.group(1)
        if ZIP_SHORT_RE.fullmatch(z):
            z = "0" + z
        return z if ZIP5_RE.fullmatch(z) else ""

    def norm_name(raw):
        s = raw.strip()
        if s.isupper() or s.islower():
            s = s.title()
        return s

    def parse_date(raw):
        s = raw.strip()
        for fmt in DATE_FORMATS:
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                continue
        raise ValueError("Unrecognized updated value: %r" % raw)

    # ---- normalize rows, drop those with no valid email/phone ----
    recs = []
    for idx, row in enumerate(rows):
        email = norm_email(get(row, "email"))
        phone = norm_phone(get(row, "phone"))
        if not email and not phone:
            continue
        source = get(row, "source").strip().lower()
        recs.append({
            "idx": idx,
            "first_name": norm_name(get(row, "first_name")),
            "last_name": norm_name(get(row, "last_name")),
            "email": email,
            "phone": phone,
            "zip": norm_zip(get(row, "zip")),
            "source": source,
            "manual": source == "manual",
            "tags": {t.strip().lower() for t in TAG_SPLIT_RE.split(get(row, "tags"))
                     if t.strip()},
            "opted_out": get(row, "opted_out").strip().lower() in OPT_OUT_VALUES,
            "updated": parse_date(get(row, "updated")),
        })

    # ---- union-find grouping ----
    n = len(recs)
    parent = list(range(n))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the smaller index as root (earliest row)
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_last_seen = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_seen:
                union(i, email_seen[r["email"]])
            else:
                email_seen[r["email"]] = i
        last = r["last_name"].lower()
        if r["phone"] and last:
            key = (r["phone"], last)
            if key in phone_last_seen:
                union(i, phone_last_seen[key])
            else:
                phone_last_seen[key] = i

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    # ---- build output, ordered by earliest row ----
    def pick(members, field):
        cands = [recs[i] for i in members if recs[i][field]]
        if not cands:
            return ""
        best = max(cands, key=lambda r: (r["manual"], r["updated"], -r["idx"]))
        return best[field]

    out = []
    for root in sorted(groups, key=lambda g: min(recs[i]["idx"] for i in groups[g])):
        members = groups[root]
        tags = set()
        for i in members:
            tags |= recs[i]["tags"]
        out.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(recs[i]["opted_out"] for i in members) else "N",
            "updated": max(recs[i]["updated"] for i in members).strftime("%Y-%m-%d"),
        })
    return out
```

Notes on how I read a few ambiguous points:

- **Opt-outs:** Because rule 9 drops rows before matching, an opted-out row with no valid email or phone is discarded and can't affect anyone. It also couldn't have been emailed anyway. For everyone else, a single opted-out row in a group sets `opted_out` to "Y". **Before sending, exclude all "Y" people from the send list.**
- **Source preference:** "manual" wins per field, so different fields in one output record can come from different rows.
- **ZIP+4:** I only treat `NNNNN-NNNN` as ZIP+4. Anything else with a hyphen becomes "".
- **Bad dates:** An unparseable `updated` value on a kept row raises `ValueError` rather than being silently guessed. Rows dropped by rule 9 are never parsed.
- **Last-name matching:** The phone + last-name match uses the normalized name lowercased, so "SMITH" and "smith" match.

